<template>
  <div class="hips-page">
    <van-nav-bar
      :title="_title"
      left-arrow
      safe-area-inset-top
      @click-left="onClickLeft"
      @click-right="onClickRight"
    >
      <template #left>
        <slot name="title-left"></slot>
      </template>
      <template #right>
        <slot name="title-right"></slot>
      </template>
    </van-nav-bar>
    <!-- <van-field
      v-if="showPda"
      ref="pda"
      v-model="pda"
      :placeholder="placeholder"
      clearable
      @keydown.enter.stop="pdaScan"
      @focus="pdaFocus"
    ></van-field> -->
    <div ref="content" class="content">
      <slot></slot>
    </div>
    <div ref="footer" class="footer">
      <slot name="footer"></slot>
    </div>
  </div>
</template>

<script>
import { NavBar, Field } from "vant";
export default {
  // 组件名称
  name: "HipsWxPage",
  // 组件参数 接收来自父组件的数据
  props: {
    title: {
      type: String,
      default: "",
    },
    initCallBack: {
      type: Function,
      default: () => {},
    },
    // hidePda: {
    //   type: Boolean,
    //   default: false,
    // },
    placeholder: {
      type: String,
      default: "pda扫码输入处",
    },
  },
  // 局部注册的组件
  components: {
    [NavBar.name]: NavBar,
    [Field.name]: Field,
  },
  // 组件状态值
  data() {
    return {
      t: null,
      height: 0,
      pda: "",
    };
  },
  // 计算属性
  computed: {
    _title() {
      return this.title || this.$route.meta.title;
    },
    // showPda() {
    //   if (this.hidePda) {
    //     return false;
    //   } else {
    //     return this.platform === "android";
    //   }
    // },
  },
  // 组件方法
  methods: {
    onClickLeft(e) {
      this.$emit("click-left", e);
    },
    onClickRight(e) {
      this.$emit("click-right", e);
    },
    initContentStyle() {
      return setInterval(() => {
        let height = document.querySelector(".hips-page").offsetHeight - 46;
        if (this.$slots["footer"]) {
          const footer = this.$refs.footer;
          height -= footer.offsetHeight;
        }
        if (this.$refs.content && height > 0) {
          const content = this.$refs.content;
          content.style.height = `${height}px`;
          typeof this.initCallBack === "function" && this.initCallBack();
        }
        // if (this.$refs["content"] && this.$slots["footer"] && this.height) {
        //   const content = this.$refs.content;
        //   const footer = this.$refs.footer;

        //   const height = this.height - footer.offsetHeight;
        //   if (height > 0) {
        //     content.style.height = `${height}px`;
        //   }
        //   typeof this.initCallBack === "function" && this.initCallBack();
        // }
      }, 2000);
    },
    onFocus(e) {
      setTimeout(() => {
        e.target.scrollIntoViewIfNeeded();
        e.target.scrollIntoView({ behavior: "smooth", block: "center" });
      }, 200);
    },
    pdaFocus() {},
    pdaScan() {
      if (this.pda === "") {
        return false;
      }
      this.$refs.pda.blur();
      setTimeout(() => {
        this.$refs.pda.focus();
      }, 500);
      this.$emit("pda-scan", this.pda);
      this.pda = "";
    },
  },
  activated() {
    this.t = this.initContentStyle();
  },
  deactivated() {
    clearInterval(this.t);
  },
  mounted() {
    this.$nextTick(() => {
      if (this.$refs["content"]) {
        this.height = this.$refs.content.offsetHeight - 46;
      }
    });
  },

  updated() {
    this.$nextTick(() => {
      const inputs = document.querySelectorAll("input");
      const textareas = document.querySelectorAll("textarea");
      inputs.forEach((item) => {
        item.removeEventListener("focus", this.onFocus);
      });
      textareas.forEach((item) => {
        item.removeEventListener("focus", this.onFocus);
      });
      inputs.forEach((item) => {
        item.addEventListener("focus", this.onFocus);
      });
      textareas.forEach((item) => {
        item.addEventListener("focus", this.onFocus);
      });
    });
  },
  unMounted() {
    clearInterval(this.t);
    const inputs = document.querySelectorAll("input");
    const textareas = document.querySelectorAll("textarea");
    inputs.forEach((item) => {
      item.removeEventListener("focus", this.onFocus);
    });
    textareas.forEach((item) => {
      item.removeEventListener("focus", this.onFocus);
    });
  },
};
</script>

<style lang="less" scoped>
@width: calc(100vw - env(safe-area-inset-left) - env(safe-area-inset-right));
@height: calc(100vh - env(safe-area-inset-top) - env(safe-area-inset-bottom));
.hips-page {
  height: 100vh;
  height: @height;
  width: @width;
  .content {
    overflow: auto;
  }
  .footer {
    width: 100vw;
    position: fixed;
    bottom: 0;
    bottom: calc(0 + env(safe-area-inset-bottom));
  }
}
</style>
