<template>
  <div ref="card" class="card" @click="onClick">
    <van-cell
      :border="false"
      :is-link="isLink"
      :center="center"
      :icon="icon"
      :required="required"
      class="first-card"
    >
      <template #title>
        <slot name="title">
          {{ replaceUndefinedToRmpty(title) }}
        </slot>
      </template>
      <template v-if="value && value !== ''" #default>
        <slot>{{ replaceUndefinedToRmpty(value) }}</slot>
      </template>
      <template #icon>
        <slot name="icon" />
      </template>
      <template #right-icon>
        <slot name="right-icon" />
      </template>
      <template #extra>
        <slot name="extra" />
      </template>
    </van-cell>
    <van-cell title="" :center="center">
      <template #label>
        <slot name="label"></slot>
      </template>
    </van-cell>
  </div>
</template>

<script>
import { Cell, Tag } from "vant";

export default {
  // 组件名称
  name: "HipsWxCard",
  // 组件参数 接收来自父组件的数据
  props: {
    // 标题
    title: {
      type: String,
      default: "",
    },
    value: {
      type: [String, Number],
      default: "",
    },
    isLink: {
      type: Boolean,
      default: false,
    },
    required: {
      type: Boolean,
      default: false,
    },
    center: {
      type: Boolean,
      default: false,
    },
    icon: {
      type: String,
      default: "",
    },
  },
  // 局部注册的组件
  components: {
    [Cell.name]: Cell,
    [Tag.name]: Tag,
  },
  // 组件方法
  methods: {
    /**'
     * 将undefined转为""
     */
    replaceUndefinedToRmpty(value) {
      return value.replace(/undefined/g, "");
    },
    onClick() {
      this.$emit("click");
    },
  },
};
</script>

<style lang="less" scoped>
