<!--
* @description 单选框
* @fileName HipsWxSingle.vue
* @author zheng yuanhou
* @date 2024/06/26 09:12:00
!-->
<template>
  <div @click="showPopup">
    <slot>
      <van-field
        v-model="_meaning"
        input-align="right"
        :disabled="_disabled"
        :required="required"
        :rules="rules"
        :label="_label"
        :readonly="readonly"
        :error="error"
        is-link
      />
    </slot>
    <van-popup
      v-model="show"
      position="bottom"
      :style="{ height: '80%' }"
      get-container="body"
      safe-area-inset-bottom
    >
      <van-nav-bar
        :title="title"
        left-arrow
        :right-text="rightText"
        @click-left.stop="onClickLeft"
        @click-right.stop="onClickRight"
      />
      <van-search
        v-model="search"
        :placeholder="placeholder"
        @search="onSearch"
      >
        <template #right-icon>
          <van-icon
            name="filter-o"
            color="green"
            :size="20"
            @click.stop="showFilter = true"
          />
        </template>
      </van-search>
      <hips-wx-list
        :loading="loading"
        :finished="finished"
        @load="onLoad"
        @refresh="onRefresh"
      >
        <van-radio-group v-model="radio">
          <hips-wx-card
            v-for="(item, index) in list"
            :key="index"
            :title="showTitle(item, index)"
            :value="item[checkValue]"
            @click="toggleRadio(item)"
          >
            <template #icon>
              <slot name="icon">
                <van-radio :name="getRadio(item)" />
              </slot>
            </template>
            <template #label>
              <slot name="label" :item="item"></slot>
            </template>
          </hips-wx-card>
        </van-radio-group>
      </hips-wx-list>
    </van-popup>
    <van-popup
      v-model="showFilter"
      position="top"
      get-container="body"
      safe-area-inset-top
    >
      <van-form
        ref="form"
        input-align="right"
        colon
        :submit-on-enter="false"
        @submit="onSubmit"
      >
        <slot name="search" />
        <div class="flex">
          <van-button size="large" native-type="reset" @click="onReset">
            重置
          </van-button>
          <van-button size="large" type="info" native-type="submit">
            确认
          </van-button>
        </div>
      </van-form>
    </van-popup>
  </div>
</template>

<script>
import {
  Field,
  Popup,
  NavBar,
  Search,
  Icon,
  Form,
  Button,
  RadioGroup,
  Radio,
  Toast,
} from "vant";
import HipsWxList from "./HipsWxList.vue";
import HipsWxCard from "./HipsWxCard.vue";
import debounce from "lodash.debounce";
import { instance } from "hips-wx-utils";
import _ from "lodash";

export default {
  // 组件名称
  name: "HipsWxSingle",
  // 组件参数 接收来自父组件的数据
  props: {
    // 是否只读，布尔类型，默认值为false
    readonly: {
      type: Boolean,
      default: false,
    },
    // 是否禁用，布尔类型，默认值为false
    disabled: {
      type: Boolean,
      default: false,
    },
    // 意义，可以是字符串或数字类型，默认值为空字符串
    meaning: {
      type: [String, Number],
      default: "",
    },
    // 标签，字符串类型，默认值为空字符串
    label: {
      type: String,
      default: "",
    },
    // 值，可以是字符串或数字类型，默认值为空字符串
    value: {
      type: [String, Number],
      default: "",
    },
    // 标题，字符串类型，默认值为空字符串
    title: {
      type: String,
      default: "",
    },
    // 右侧文本，字符串类型，默认值为空字符串
    rightText: {
      type: String,
      default: "",
    },
    // 占位符，字符串类型，默认值为空字符串
    placeholder: {
      type: String,
      default: "",
    },
    // 搜索关键字，字符串类型，默认值为空字符串
    searchKey: {
      type: String,
      default: "",
    },
    // 单个数据，可以是数组类型或未定义，默认值为未定义
    singleData: {
      type: [Array, undefined],
      default: undefined,
    },
    // 关联代码，字符串类型，默认值为空字符串
    lovCode: {
      type: String,
      default: "",
    },
    // 关联URL，字符串类型，默认值为空字符串
    lovUrl: {
      type: String,
      default: "",
    },
    // 参数，对象类型，默认值为空对象
    params: {
      type: Object,
      default: () => ({}),
    },
    // 校验标题，字符串类型，默认值为空字符串
    checkTitle: {
      type: String,
      default: "",
    },
    // 校验值，字符串类型，默认值为空字符串
    checkValue: {
      type: String,
      default: "",
    },
    // 选择单选框，可以是字符串或数组类型，默认值为空字符串
    checkRadio: {
      type: [String, Array],
      default: "",
    },
    // 是否必填，布尔类型，默认值为false
    required: {
      type: Boolean,
      default: false,
    },
    // 规则，数组类型，默认值为空数组
    rules: {
      type: Array,
      default: () => [],
    },
    // 是否出错，布尔类型，默认值为false
    error: {
      type: Boolean,
      default: false,
    },
    // 是否显示数字，布尔类型，默认值为false
    showNumber: {
      type: Boolean,
      default: false,
    },
    // 级联，数组类型，默认值为空数组
    cascades: {
      type: Array,
      default: () => [],
    },
    // 尺寸，数字类型，默认值为10
    size: {
      type: Number,
      default: 10,
    },
  },
  // 局部注册的组件
  components: {
    [Field.name]: Field,
    [Popup.name]: Popup,
    [NavBar.name]: NavBar,
    [Search.name]: Search,
    [Icon.name]: Icon,
    [Form.name]: Form,
    [Button.name]: Button,
    [RadioGroup.name]: RadioGroup,
    [Radio.name]: Radio,
    [HipsWxList.name]: HipsWxList,
    [HipsWxCard.name]: HipsWxCard,
  },
  // 组件状态值
  data() {
    return {
      // 控制弹窗或特定组件的显示状态
      show: false,

      // 搜索关键词输入框的绑定值
      search: "",

      // 筛选功能的显示状态
      showFilter: false,

      // 存储筛选条件的参数
      filterParams: {},

      // 加载状态，用于显示加载中的动画或提示
      loading: false,

      // 数据加载完成的状态，用于显示没有更多数据的提示
      finished: false,

      // 存储从后端获取的数据列表
      list: [],

      // 当前的页码，用于分页请求
      page: 0,

      // 存储对比功能的参数
      compareParams: {},
    };
  },
  // 计算属性
  computed: {
    /**
     * 返回当前组件的标签文本
     * 如果当前组件的 label 属性存在，则返回 label，否则返回 title
     */
    _label() {
      return this.label || this.title;
    },

    /**
     * 获取和设置当前组件的意义值（meaning）
     */
    _meaning: {
      get() {
        // 返回当前组件的 meaning 属性值
        return this.meaning;
      },
      set(v) {
        // 当设置 meaning 属性值时，触发 update:meaning 事件，将新值传递给父组件
        this.$emit("update:meaning", v);
      },
    },

    /**
     * 获取和设置当前组件的 radio 值
     */
    radio: {
      get() {
        // 返回当前组件的 value 属性值
        return this.value;
      },
      set(v) {
        // 当设置 radio 值时，触发 input 事件，将新值传递给父组件
        this.$emit("input", v);
      },
    },

    /**
     * 检查并返回适当的 radio 值
     * 此函数首先检查 checkRadio 属性是否为空字符串、null 或 undefined
     * 如果 checkRadio 不符合上述条件，则返回 checkValue
     * 否则，返回 checkRadio
     */
    _checkRadio() {
      // 获取 checkRadio 和 checkValue 的值，减少多次访问对象属性的开销
      const checkRadio = this.checkRadio;
      const checkValue = this.checkValue;

      // 检查 checkRadio 是否为空字符串、null 或 undefined
      if (
        typeof checkRadio !== "string" ||
        checkRadio === "" ||
        checkRadio === null ||
        checkRadio === undefined
      ) {
        // 返回 checkValue
        return checkValue;
      }

      // 返回 checkRadio
      return checkRadio;
    },

    // /**
    //  * 返回当前组件的参数对象
    //  * 此函数调用 getParams 方法来获取参数对象
    //  */
    // params() {
    //   return {
    //     ...this.params,
    //   };
    // },

    /**
     * 计算并返回当前组件的禁用状态
     * 此函数通过一系列检查来确定组件是否应被禁用
     */
    _disabled() {
      // 获取有效的级联属性值
      const cascades = this._getValidCascades();
      // 获取有效的参数值
      const params = this._getValidParams();
      // 检查参数是否未定义
      const flag = this._checkUndefinedParams(cascades, params);
      // 获取禁用状态
      const disabled = this._getDisabledState();
      // 如果 flag 为真或组件被禁用，则返回 true，否则返回 false
      return flag || disabled;
    },
  },
  watch: {
    params: {
      handler(newValue) {
        const { cascades = [], compareParams = {} } = this;
        if (cascades.length <= 0) {
          return false;
        } else {
          const flag = cascades.every((key) => {
            return newValue[key] !== compareParams[key];
          });
          if (flag) {
            this.radio = "";
            this._meaning = "";
          }
        }
      },
      deep: true,
    },
  },
  // 组件方法
  methods: {
    /**
     * @description: 点击左侧按钮时触发
     * @return {*}
     */
    onClickLeft() {
      this.hiddenPopup();
      this.$emit("click-left");
    },

    /**
     * @description: 点击右侧按钮时触发
     * @return {*}
     */
    onClickRight() {
      this.hiddenPopup();
      this.$emit("click-right");
    },

    /**
     * @description: 显示弹出层
     * @return {boolean} 返回一个布尔值，表示弹出层是否应该显示
     */
    showPopup() {
      if (this.readonly || this._disabled) {
        return false;
      }

      if (!this.params || !this.compareParams) {
        console.error("Either params or compareParams is null or undefined");
        return false;
      }

      let paramsEqual = true;
      for (const key in this.params) {
        if (
          Object.prototype.hasOwnProperty.call(this.params, key) &&
          this.params[key] !== this.compareParams[key]
        ) {
          paramsEqual = false;
          break;
        }
      }
      if (!paramsEqual) {
        try {
          this.onRefresh()
            .then(() => {
              this.handleList();
            })
            .catch((error) => {
              console.error("Error refreshing:", error);
            });
        } catch (error) {
          console.error("Error refreshing:", error);
        }
        return false;
      } else {
        this.handleList();
      }
    },

    handleList() {
      if (this.list.length === 1) {
        this.radio = this.list[0][this.checkRadio];
        this._meaning = this.list[0][this.checkTitle];
      } else {
        this.show = true;
      }
    },

    /**
     * @description: 隐藏弹出层
     * @return {*}
     */
    hiddenPopup() {
      this.show = false;
    },

    /**
     * @description: 确认选择
     * @param {*} params 选择的参数
     * @return {*}
     */
    onSubmit: debounce(function (params = {}) {
      this.filterParams = params;
      this.showFilter = false;
      this.onSearch();
    }, 200),

    /**
     * @description: 重置查询条件
     * @return {*}
     */
    onReset() {
      this.$emit("reset");
    },

    /**
     * @description: 查询
     * @return {*}
     */
    onSearch: debounce(function () {
      this.onRefresh();
    }, 200),

    /**
     * @description: 刷新数据
     * @return {Promise} 返回一个Promise对象，表示数据刷新的过程
     */
    onRefresh() {
      this.list = [];
      this.page = 0;
      return this.onLoad();
    },

    /**
     * @description: 加载数据
     * @return {Promise} 返回一个Promise对象，表示数据加载的过程
     */
    onLoad() {
      this.compareParams = JSON.parse(JSON.stringify(this.params));
      return new Promise((resolve, reject) => {
        if (this.loading) {
          resolve();
        } else {
          this.loading = true;
          if (this.singleData) {
            this.initSingleData();
            resolve();
          } else {
            this.fetchData()
              .then((res) => {
                this.handleResponse(res);
                resolve();
              })
              .catch((error) => {
                this.handleError(error);
                reject(error);
              })
              .finally(() => {
                this.loading = false;
              });
          }
        }
      });
    },

    /**
     * @description: 获取数据
     * @return {Promise} 返回一个Promise对象，表示数据获取的过程
     */
    fetchData() {
      const lovUrl = this.getLovUrl();
      const params = this.getParams();
      return instance.get(lovUrl, { params });
    },

    /**
     * @description: 处理响应数据
     * @param {*} res 响应的数据
     * @return {*}
     */
    handleResponse(res) {
      if (Array.isArray(res)) {
        this.contentIsArray(res);
        this.finished = res.length < this.size;
      } else if (typeof res === "object") {
        this.contentIsObject(res);
      } else {
        console.warn("Unexpected response type:", typeof res);
        this.finished = true;
      }
      this.page++;
    },

    /**
     * @description: 处理错误
     * @param {*} error 错误对象
     * @return {*}
     */
    handleError(error) {
      console.error("Error in onLoad:", error);
      Toast.fail(error.message);
      this.finished = true;
    },
    /**
     * 获取传参参数
     */
    getParams() {
      const {
        filterParams = {},
        page = 0,
        search = "",
        searchKey = "",
        params = {},
      } = this;

      // 验证输入
      const validatedSearch = _.escape(search);
      const validatedFilterParams = _.mapValues(filterParams, (value) =>
        _.escape(value)
      );

      // 合并参数
      const combinedParams = {
        ...params,
        ...validatedFilterParams,
        page,
        size: this.size || 10, // 提供默认值
      };

      // 处理 search 为 null 或 undefined 的情况
      if (searchKey && search !== null && search !== undefined) {
        combinedParams[searchKey] = validatedSearch;
      }

      return combinedParams;
    },

    /**
     * @description: 获取接口地址
     * @return {*}
     */
    getLovUrl() {
      if (this.lovUrl) {
        return this.lovUrl;
      }
      return "/hpfm/v1/#tenantId#/lovs/data?lovCode=" + this.lovCode;
    },

    /**
     * @description: 初始化单选数据
     */
    initSingleData() {
      const reg = new RegExp(this.search);
      this.list = this.singleData.filter((item) => {
        return reg.test(item[this.searchKey]);
      });
      this.loading = false;
      this.finished = true;
    },

    /**
     * @description: 接口直接返回数组
     * @return {*}
     */
    contentIsArray(array) {
      // this.finished = true;
      this.addList(array);
    },

    /**
     * @description: 接口返回Object
     * @return {*}
     */
    contentIsObject(obj) {
      const { failed = false, message, content = [] } = obj;
      if (failed) {
        this.contentIsFailed(message);
      } else {
        if (content.length < 10) {
          this.finished = true;
        }
        this.addList(content);
      }
    },

    /**
     * @description: 添加列表项
     * @param {Array} array - 要添加的列表项数组
     */
    addList(array = []) {
      const reg = new RegExp(RegExp.escape(this.params[this.searchKey]));

      if (array.length === 0) {
        return;
      }

      const existingItems = new Set(
        this.list.map((_item) => _item[this._checkRadio])
      );

      array.forEach((item) => {
        try {
          if (reg.test(item[this.searchKey])) {
            if (!existingItems.has(item[this._checkRadio])) {
              this.list.push(item);
              existingItems.add(item[this._checkRadio]);
            }
          }
        } catch (error) {
          console.error("Error in regex test or property access:", error);
        }
      });
    },

    /**
     * @description: 接口返回报错
     * @param {string} message - 错误信息
     */
    contentIsFailed(message) {
      this.finished = true;
      Toast.fail({
        message,
        duration: 2000,
      });
    },
    /**
     * @description: 获取单选值
     * @param {Object} obj - 当前项对象
     * @return {string|*} - 单选值字符串或原始值
     */
    getRadio(obj = {}) {
      const radioKeys = this["_checkRadio"];

      // 检查 _checkRadio 是否存在且类型正确
      if (typeof radioKeys === "undefined" || radioKeys === null) {
        console.error("_checkRadio is not defined or null");
        return "";
      }

      // 检查 radioKeys 是否为数组
      if (Array.isArray(radioKeys)) {
        // 验证数组内容
        if (!radioKeys.every((key) => typeof key === "string")) {
          console.error("Invalid keys in _checkRadio array");
          return "";
        }

        // 使用 reduce 方法构建字符串
        const str = radioKeys.reduce((acc, key) => {
          if (Object.prototype.hasOwnProperty.call(obj, key)) {
            return acc + (acc ? "-" : "") + obj[key];
          } else {
            console.warn(`Key ${key} does not exist in the object`);
            return acc;
          }
        }, "");
        return str;
      }

      // 检查单个键是否存在
      if (
        typeof radioKeys === "string" &&
        Object.prototype.hasOwnProperty.call(obj, radioKeys)
      ) {
        return obj[radioKeys];
      }

      // 异常处理
      console.error("Invalid _checkRadio value");
      return "";
    },

    /**
     * @description: 切换单选项
     * @param {Object} item - 当前项对象
     */
    toggleRadio(item = {}) {
      try {
        const checkRadio = this._checkRadio || "";
        const checkTitle = this.checkTitle || "";

        if (!item || !Object.keys(item).length) {
          // 如果 item 是空对象或 undefined
          return;
        }

        const radioValue = item[checkRadio];
        const titleValue = item[checkTitle];

        if (this.radio === radioValue) {
          this.radio = "";
          this._meaning = "";
          this.$emit("confirm", {});
        } else {
          this.radio = radioValue;
          this._meaning = titleValue;
          this.$emit("confirm", item);
        }

        this.hiddenPopup();
      } catch (error) {
        console.error("Error in toggleRadio:", error);
      }
    },

    /**
     * @description: 显示标题
     * @param {Object} item - 当前项对象
     * @param {number} index - 当前项索引
     * @return {string} - 标题字符串
     */
    showTitle(item, index) {
      if (this.showNumber) {
        return `${index + 1}.${item[this.checkTitle]}`;
      }
      return item[this.checkTitle];
    },

    /**
     * @description: 获取有效的级联选择值数组
     * @return {Array} - 有效的级联选择值数组
     */
    _getValidCascades() {
      return Array.isArray(this.cascades) ? this.cascades : [];
    },

    /**
     * @description: 获取有效的参数对象
     * @return {Object} - 有效的参数对象
     */
    _getValidParams() {
      return this.params || {};
    },

    /**
     * @description: 检查参数中是否包含未定义的级联选择值
     * @param {Array} cascades - 级联选择值数组
     * @param {Object} params - 参数对象
     * @return {boolean} - 是否包含未定义的级联选择值
     */
    _checkUndefinedParams(cascades, params) {
      return !cascades.every(
        (item) => ![undefined, "", null].includes(params[item])
      );
    },

    /**
     * @description: 获取禁用状态
     * @return {boolean} - 禁用状态
     */
    _getDisabledState() {
      return this.disabled || false;
    },
  },
};
</script>

