<template>
  <div>
    <!-- 使用 v-model 绑定搜索框的值，通过 clearable 属性添加清除功能 -->
    <van-search v-model="_value" clearable @seach="onSearch">
      <template #right-icon>
        <div class="flex">
          <!-- 根据 showFilter 控制过滤图标的显示 -->
          <van-icon
            v-show="showFilter"
            name="filter-o"
            size="24"
            :color="color"
            @click.stop="show = true"
          />
          <!-- 根据 showScan 控制扫描图标的显示 -->
          <van-icon
            v-show="showScan"
            name="scan"
            size="24"
            :color="color"
            @click.stop="onScan"
          />
        </div>
      </template>
    </van-search>
    <!-- 使用 van-popup 实现顶部弹出层 -->
    <van-popup v-model="show" position="top" :get-container="getContainer">
      <div class="filter">
        <div v-for="(item, index) in filterList" :key="index">
          <van-field
            v-if="item.type === 'text'"
            v-model="item.value"
            :label="item.label"
            input-align="right"
            clearable
          />
          <hips-wx-single
            v-else-if="item.type === 'single'"
            v-model="item.value"
            :meaning.sync="item.meaning"
            :title="item.label"
            :lov-code="item.lovCode"
            :lov-url="item.lovUrl"
            :single-data="item.singleData"
            :search-key="item.searchKey"
            :check-title="item.checkTitle"
            :check-radio="item.checkRadio"
            :check-value="item.checkValue"
            input-align="right"
          />
          <hips-wx-multiple
            v-else-if="item.type === 'multiple'"
            v-model="item.value"
            :meaning.sync="item.meaning"
            :title="item.label"
            :lov-code="item.lovCode"
            :lov-url="item.lovUrl"
            :single-data="item.singleData"
            :search-key="item.searchKey"
            :check-title="item.checkTitle"
            :check-radio="item.checkRadio"
            :check-value="item.checkValue"
            input-align="right"
          />
          <hips-wx-date
            v-else-if="item.type === 'date'"
            v-model="item.value"
            :label="item.label"
            :formatter="item.formatter"
            input-align="right"
            clickable
          />
        </div>
      </div>
      <div class="footer">
        <van-button type="warning" @click="onReset"> 重置 </van-button>
        <van-button type="info" @click="onFilter"> 查询 </van-button>
      </div>
    </van-popup>
  </div>
</template>

<script>
import { Search, Button, Popup, Field, Toast } from "vant";
import { bridge } from "hips-wx-utils";

import HipsWxSingle from "./HipsWxSingle.vue";
import HipsWxDate from "./HipsWxDate.vue";
import HipsWxMultiple from "./HipsWxMultiple.vue";

export default {
  name: "HipsWxFilter",
  props: {
    // 定义 getContainer 属性，用于指定弹出层的父节点
    getContainer: [String, () => Element],
    // 定义 value 属性，用于接收外部的搜索值
    value: {
      type: String,
      default: "",
    },
    // 定义 color 属性，用于自定义图标颜色
    color: {
      type: String,
      default: "#07c160",
    },
    // 定义 placeholder 属性，用于自定义搜索框占位符
    placeholder: {
      type: String,
      default: "请输入搜索内容",
    },
    // 定义 showFilter 属性，控制过滤图标的显示
    showFilter: {
      type: Boolean,
      default: false,
    },
    // 定义 showScan 属性，控制扫描图标的显示
    showScan: {
      type: Boolean,
      default: false,
    },
    searchList: {
      type: Array,
      default: () => [],
    },
  },
  // 局部注册的组件
  components: {
    [Search.name]: Search,
    [Button.name]: Button,
    [Popup.name]: Popup,
    [Field.name]: Field,
    [HipsWxSingle.name]: HipsWxSingle,
    [HipsWxDate.name]: HipsWxDate,
    [HipsWxMultiple.name]: HipsWxMultiple,
  },
  // 组件状态值
  data() {
    return {
      // 控制弹出层的显示状态
      show: false,
      filterList: [],
    };
  },
  // 计算属性
  computed: {
    // 同步外部传入的 value 值
    _value: {
      get() {
        return this.value;
      },
      set(v) {
        this.$emit("input", v);
      },
    },
    // _searchList: {
    //   get() {
    //     return this.searchList.map((item) => {
    //       const {
    //         name = "",
    //         value = "",
    //         meaning = "",
    //         label = "",
    //         type = "text",
    //         lovCode = "",
    //         lovUrl = "",
    //         singleData = [],
    //         searchKey = "",
    //         checkTitle = "",
    //         checkRadio = "",
    //         checkValue = "",
    //       } = item;
    //       return {
    //         name,
    //         value,
    //         meaning,
    //         label,
    //         type,
    //         lovCode,
    //         lovUrl,
    //         singleData,
    //         searchKey,
    //         checkTitle,
    //         checkRadio,
    //         checkValue,
    //       };
    //     });
    //   },
    //   set(list) {
    //     this.$emit("update:searchList", list);
    //   },
    // },
  },
  // 组件方法
  methods: {
    // 筛选方法，收集筛选条件并触发 filter 事件
    onFilter() {
      const data = {};
      this.filterList.forEach((item) => {
        data[item.name] = item.value;
      });
      this.$emit("filter", data);
      this.hiddenShow();
    },
    // 重置方法，清空筛选条件并触发 reset 事件
    onReset() {
      this.filterList.forEach((item) => {
        item.value = "";
        item.meaning = "";
      });
      this.$emit("reset", {});
    },
    // 点击扫描图标时触发扫描功能
    onScan() {
      try {
        bridge.scan().then((res) => {
          this.$emit("scan", res);
        });
      } catch (error) {
        Toast.fail(error.message);
      }
    },
    // 点击搜索按钮时触发搜索事件
    onSearch() {
      this.$emit("search", this._value);
    },
    // 隐藏弹出层
    hiddenShow() {
      this.show = false;
    },
  },
  // 路由组件被激活时触发
  activated() {},
  // 路由组件失活时触发
  deactivated() {},
  // 组件生成时触发
  created() {
    this.filterList = this.searchList.map((item) => {
      const {
        name = "",
        value = "",
        meaning = "",
        label = "",
        type = "text",
        lovCode = "",
        lovUrl = "",
        singleData = [],
        searchKey = "",
        checkTitle = "",
        checkRadio = "",
        checkValue = "",
        formatter = "",
      } = item;
      return {
        name,
        value,
        meaning,
        label,
        type,
        lovCode,
        lovUrl,
        singleData,
        searchKey,
        checkTitle,
        checkRadio,
        checkValue,
        formatter,
      };
    });
  },
  // 组件生成完毕后触发
  mounted() {},
};
</script>

<style lang="less" scoped>
// 使用 flex 布局排列图标，并设置图标间的间距
.flex {
  display: flex;
  .van-icon + .van-icon {
    margin-left: 1vw;
  }
}
// 设置筛选弹出层的样式
.filter {
  max-height: 40vh;
  overflow-y: auto;
}
.footer {
  display: flex;
  .van-button {
    flex: 1;
  }
}
</style>
