<template>
  <div @click="showPopup()">
    <slot>
      <van-field
        v-model="_meaning"
        readonly
        is-link
        :colon="colon"
        :required="required"
        :input-align="inputAlign"
        :disabled="disabled"
        :label="_label"
      />
    </slot>
    <van-popup
      v-model="show"
      position="bottom"
      :style="{ height: '80%' }"
      get-container="body"
      safe-area-inset-bottom
    >
      <van-nav-bar
        :title="title"
        left-arrow
        :right-text="rightText"
        @click-left.stop="onClickLeft"
        @click-right.stop="onClickRight"
      />
      <van-search v-model="search" :placeholder="placeholder">
        <template #right-icon>
          <van-icon
            name="filter-o"
            color="green"
            :size="20"
            @click.stop="showFilter = true"
          />
        </template>
      </van-search>
      <HipsWxList
        :loading="loading"
        :finished="finished"
        @load="onLoad"
        @refresh="onRefresh"
      >
        <van-checkbox-group v-model="check">
          <HipsWxCard
            v-for="(item, index) in list"
            :key="index"
            :title="item[checkTitle]"
            :value="item[checkValue]"
            @click="toggleRadio(item)"
          >
            <template #icon>
              <slot name="icon">
                <van-checkbox :name="initRadio(item)" shape="square" />
              </slot>
            </template>
            <template #label>
              <slot name="label" :item="item"></slot>
            </template>
          </HipsWxCard>
        </van-checkbox-group>
      </HipsWxList>
    </van-popup>
    <van-popup
      v-model="showFilter"
      position="top"
      get-container="body"
      safe-area-inset-top
    >
      <van-form
        ref="form"
        input-align="right"
        colon
        :submit-on-enter="false"
        @submit="onSubmit"
      >
        <slot name="search" />
        <div class="flex">
          <van-button size="large" native-type="reset" @click="onReset">
            重置
          </van-button>
          <van-button size="large" type="info" native-type="submit">
            确认
          </van-button>
        </div>
      </van-form>
    </van-popup>
  </div>
</template>

<script>
import {
  Field,
  Popup,
  NavBar,
  Search,
  Icon,
  Form,
  Button,
  CheckboxGroup,
  Checkbox,
  Toast,
} from "vant";
import HipsWxList from "./HipsWxList.vue";
import HipsWxCard from "./HipsWxCard.vue";
import debounce from "lodash.debounce";
import { instance } from "hips-wx-utils";

export default {
  // 组件名称
  name: "HipsWxMultiple",
  // 组件参数 接收来自父组件的数据
  props: {
    /**
     * 只读
     */
    readonly: {
      type: Boolean,
      default: false,
    },
    /**
     * 是否可编辑
     */
    disabled: {
      type: Boolean,
      default: false,
    },
    meaning: {
      type: String,
      default: "",
    },
    label: {
      type: String,
      default: "",
    },
    value: {
      type: String,
      default: "",
    },
    title: {
      type: String,
      default: "",
    },
    rightText: {
      type: String,
      default: "确认",
    },
    placeholder: {
      type: String,
      default: "",
    },
    searchKey: {
      type: String,
      default: "",
    },
    singleData: {
      type: Array,
      default: () => [],
    },
    lovCode: {
      type: String,
      default: "",
    },
    lovUrl: {
      type: String,
      default: "",
    },
    params: {
      type: Object,
      default: () => ({}),
    },
    checkTitle: {
      type: String,
      default: "",
    },
    checkValue: {
      type: String,
      default: "",
    },
    checkRadio: {
      type: [String, Array],
      default: "",
    },
    required: {
      type: Boolean,
      default: false,
    },
    inputAlign: {
      type: String,
      default: "right",
    },
    colon: {
      type: Boolean,
      default: false,
    },
  },
  // 局部注册的组件
  components: {
    [Field.name]: Field,
    [Popup.name]: Popup,
    [NavBar.name]: NavBar,
    [Search.name]: Search,
    [Icon.name]: Icon,
    [Form.name]: Form,
    [Button.name]: Button,
    [CheckboxGroup.name]: CheckboxGroup,
    [Checkbox.name]: Checkbox,
    HipsWxList,
    HipsWxCard,
  },
  // 组件状态值
  data() {
    return {
      show: false,
      search: "",
      showFilter: false,
      filterParams: {},
      loading: false,
      finished: false,
      list: [],
      page: 0,
      checked: [],
      t: null,
    };
  },
  // 计算属性
  computed: {
    _label() {
      return this.label || this.title;
    },
    _meaning: {
      get() {
        return this.meaning;
      },
      set(v) {
        this.$emit("update:meaning", v);
      },
    },
    check: {
      get() {
        return this.value.split(",");
      },
      set(v) {
        this.$emit("input", v.join(","));
      },
    },
    _checkRadio() {
      if (this.checkRadio === "") {
        return this.checkValue;
      }
      return this.checkRadio;
    },
  },
  // 侦听器
  watch: {
    show(newVal) {
      clearTimeout(this.t);
      this.t = setTimeout(() => {
        if (!newVal) {
          this.checked = this.check.map((item) => {
            return this.list.find((_item) => _item[this.checkRadio] === item);
          });
          this.$emit("confirm", this.checked);
        }
      }, 200);
    },
    // params: {
    //   handler(newVal, oldVal) {
    //     clearTimeout(this.t);
    //     this.t = setTimeout(() => {
    //       if (JSON.stringify(newVal) !== JSON.stringify(oldVal)) {
    //         this.checked = [];
    //         this.onRefresh();
    //       }
    //     }, 200);
    //   },
    //   deep: true,
    // },
  },
  // 组件方法
  methods: {
    /**
     * 退出
     */
    onClickLeft() {
      this.hiddenPopup();
      this.$emit("click-left", this.checked);
    },
    /**
     * 确认
     */
    onClickRight() {
      this.hiddenPopup();
      this.$emit("click-right", this.checked);
    },
    /**
     * 显示选择层
     */
    showPopup() {
      if (this.readonly) {
        return false;
      }
      if (this.disabled) {
        return false;
      }
      this.show = true;
    },
    /**
     * 关闭选择层
     */
    hiddenPopup() {
      this.show = false;
    },
    /**
     * @description: 确认选择
     * @param {*} function
     * @return {*}
     */
    onSubmit: debounce(function (params) {
      this.filterParams = params;
      this.showFilter = false;
      this.onSearch();
    }, 200),
    /**
     * @description: 重置查询条件
     * @return {*}
     */
    onReset() {
      this.$emit("reset");
    },
    /**
     * @description: 查询
     * @param {*} function
     * @return {*}
     */
    onSearch: debounce(function () {
      this.onRefresh();
    }, 200),
    /**
     * 初始化
     */
    onRefresh() {
      this.list = [];
      this.page = 0;
      this.onLoad();
    },
    /**
     * 加载数据
     */
    async onLoad() {
      if (this.loading) {
        return false;
      }
      this.loading = true;
      if (this.singleData.length > 0) {
        this.initSingleData();
      } else {
        const params = this.getParams();
        const lovUrl = this.getLovUrl();
        instance
          .get(lovUrl, { params })
          .then((res) => {
            this.page++;
            if (Array.isArray(res)) {
              this.contentIsArray(res);
              this.finished = res.length < 10;
            } else if (typeof res === "object") {
              this.contentIsObject(res);
            } else {
              this.finished = true;
            }
          })
          .catch((error) => {
            Toast.fail(error.message);
            this.finished = true;
          })
          .finally(() => {
            this.loading = false;
          });
      }
      // if (this.singleData.length > 0) {
      //   const reg = new RegExp(this.search);
      //   this.list = this.singleData.filter((item) => {
      //     return reg.test(item[this.searchKey]);
      //   });
      //   this.loading = false;
      //   this.finished = true;
      // } else {
      //   if (this.loading) {
      //     return false;
      //   }
      //   this.loading = true;
      //   const params = this.getParams();
      //   const lovUrl = this.getLovUrl();
      //   this.page++;
      //   const content = await instance.get(lovUrl, { params });
      //   this.loading = false;
      //   if (Array.isArray(content)) {
      //     this.contentIsArray(content);
      //   } else if (typeof content === "object") {
      //     this.contentIsObject(content);
      //   } else {
      //     this.list.finished = true;
      //   }
      // }
    },
    /**
     * 获取传参参数
     */
    getParams() {
      const { params, page, search, filterParams, searchKey } = this;
      return {
        ...params,
        ...filterParams,
        page,
        size: 10,
        [searchKey]: search,
      };
    },
    /**
     * @description: 获取接口地址
     * @return {*}
     */
    getLovUrl() {
      if (this.lovUrl) {
        return this.lovUrl;
      }
      return "/hpfm/v1/#tenantId#/lovs/data?lovCode=" + this.lovCode;
    },
    initSingleData() {
      const reg = new RegExp(this.search);
      this.list = this.singleData.filter((item) => {
        return reg.test(item[this.searchKey]);
      });
      this.loading = false;
      this.finished = true;
    },
    /**
     * @description: 接口直接返回数组
     * @return {*}
     */
    contentIsArray(array) {
      array.forEach((item) => {
        this.list.push(item);
      });
    },
    /**
     * @description: 接口返回Object
     * @return {*}
     */
    contentIsObject(obj) {
      const { failed = false, message, content = [] } = obj;
      if (failed) {
        this.contentIsFailed(message);
      } else {
        content.forEach((item) => {
          this.list.push(item);
        });
        this.finished = content.length < 10;
      }
    },
    /**
     * @description: 接口返回报错
     * @return {*}
     */
    contentIsFailed(message) {
      this.finished = true;
      Toast.fail({
        message,
        duration: 2000,
      });
    },
    /**
     * 初始化radio
     */
    initRadio(obj) {
      const checkRadio = this["_checkRadio"];

      if (Array.isArray(checkRadio)) {
        const str = checkRadio.map((key) => obj[key]).join("-");
        return str;
      }
      return obj[checkRadio];
    },
    /**
     * 多选
     */
    toggleRadio(item) {
      const check = this.check;
      const meanings = this._meaning.split(",");
      const checkSet = new Set(check);
      checkSet.delete("");
      const meaningSet = new Set(meanings);
      meaningSet.delete("");
      const checkRadio = this.checkRadio;
      const checkTitle = this.checkTitle;
      if (checkSet.has(item[checkRadio])) {
        checkSet.delete(item[checkRadio]);
        meaningSet.delete(item[checkTitle]);
      } else {
        checkSet.add(item[checkRadio]);
        meaningSet.add(item[checkTitle]);
      }
      this._meaning = Array.from(meaningSet).join(",");
      this.check = Array.from(checkSet);
      this.checked = this.check.map((key) => {
        return this.list.find((obj) => obj[checkRadio] === key);
      });
    },
  },
};
</script>

<style lang="less" scoped>
/deep/.van-list {
  height: 64vh;
  background-color: rgba(204, 204, 204, 0.5);
  .van-checkbox-group {
    .van-cell {
      .van-checkbox {
        margin-right: 2vw;
      }
    }
    .card + .card {
      margin-top: 1px;
    }
  }
}
</style>
